import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.C-si7TFR.js";const d=JSON.parse(`{"title":"IOLinker Agent","description":"The IOLinker Agent (AI Agent) is capable of perceiving its environment, autonomously analyzing information, making decisions, and executing actions to achieve specific goals. It supports the configuration of MCP tools to extend the Agent's interaction with the external environment. Additionally, it features a memory function that enables coherent conversations.","frontmatter":{"title":"IOLinker Agent","description":"The IOLinker Agent (AI Agent) is capable of perceiving its environment, autonomously analyzing information, making decisions, and executing actions to achieve specific goals. It supports the configuration of MCP tools to extend the Agent's interaction with the external environment. Additionally, it features a memory function that enables coherent conversations.","meta":[{"name":"keywords"},{"content":"Agent, AI Agent, ReAct Framework, MCP Server Tools, Agent Memory, Reasoning, Large Language Models, Low-Code, AI Workflow, Process Engine"}]},"headers":[],"relativePath":"iolinker_agent.md","filePath":"iolinker_agent.md"}`),i={name:"iolinker_agent.md"};function s(r,e,l,c,h,p){return a(),n("div",null,[...e[0]||(e[0]=[o(`<h2 id="iolinker-agent" tabindex="-1">IOLinker Agent <a class="header-anchor" href="#iolinker-agent" aria-label="Permalink to &quot;IOLinker Agent&quot;">​</a></h2><h3 id="create-llm-credential" tabindex="-1">Create LLM Credential <a class="header-anchor" href="#create-llm-credential" aria-label="Permalink to &quot;Create LLM Credential&quot;">​</a></h3><p>Create an LLM API key credential in <strong>App Development &gt; Credential</strong>. Currently supported LLM models include: Deepseek, Doubao, Kimi, OpenAI, Qwen, and the open-source Ollama.</p><blockquote><p>The original image contained a credential, token or application identifier and is excluded from publication. Create and enter your own secret in the local configuration.</p></blockquote><h3 id="configure-iolinker-agent" tabindex="-1">Configure IOLinker Agent <a class="header-anchor" href="#configure-iolinker-agent" aria-label="Permalink to &quot;Configure IOLinker Agent&quot;">​</a></h3><p>Here you can use it in combination with the Telegram trigger. You can send messages to the Agent via Telegram, and the app will deliver the Agent&#39;s processing results back to the user through Telegram messages.</p><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote><h3 id="test-iolinker-agent" tabindex="-1">Test IOLinker Agent <a class="header-anchor" href="#test-iolinker-agent" aria-label="Permalink to &quot;Test IOLinker Agent&quot;">​</a></h3><p>We can open the configured Telegram bot and interact with it directly. For example, if you ask it &quot;What can you do?&quot;, it will provide a response message based on the current environment and the external tools it can utilize. Each reply from the bot generates an execution record in the <code>Execution List</code>.</p><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote><p>Double-clicking the app will display the current app&#39;s output.</p><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote><p>Right-click to view the conversation history:</p><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote><h3 id="tool-call" tabindex="-1">Tool call <a class="header-anchor" href="#tool-call" aria-label="Permalink to &quot;Tool call&quot;">​</a></h3><p>When we want to check the weather, the Agent finds a corresponding MCP tool, which automatically plans the request parameters and initiates the call.</p><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote><p>The previous second screenshot referenced an unavailable author-local file. Use the preceding tool-call image and the current conversation interface as the reference.</p><p>Since the Agent invoked MCP tools, in addition to the Agent&#39;s execution records, there is also an MCP execution record here.</p><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote><p>We can view the complete interaction process between the Agent and the user in the execution details, as well as observe how it reasons and invokes tools.</p><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote><h2 id="input" tabindex="-1">Input <a class="header-anchor" href="#input" aria-label="Permalink to &quot;Input&quot;">​</a></h2><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote><h3 id="api-key" tabindex="-1">API Key <a class="header-anchor" href="#api-key" aria-label="Permalink to &quot;API Key&quot;">​</a></h3><p>You can choose to create an LLM API key in <strong>App Development &gt; Credential</strong>.</p><h3 id="model" tabindex="-1">Model <a class="header-anchor" href="#model" aria-label="Permalink to &quot;Model&quot;">​</a></h3><p>The system will return a list of supported models based on the currently selected LLM vendor platform type. If a model is not in the returned drop-down list, you can enter it directly in the edit box.</p><h3 id="framework" tabindex="-1">Framework <a class="header-anchor" href="#framework" aria-label="Permalink to &quot;Framework&quot;">​</a></h3><p><strong>ReAct</strong> is a framework that enables AI agents to solve problems through <strong>reasoning</strong> and <strong>action</strong>. Its core concept is: <strong>instead of having the AI provide answers directly, it engages in a human-like cycle of &quot;think-act-think-again&quot; to complete tasks.</strong></p><p>The workflow of ReAct follows a typical loop, which can be summarized into the following three steps, repeated iteratively until the problem is resolved:</p><p><strong>though → action → observation</strong></p><ol><li><p><strong>Thinking</strong></p><p>The AI analyzes the current problem and the information it has already obtained. <strong>Key:</strong> The AI must write down its thought process. <strong>For example:</strong> &quot;The user asked about today&#39;s weather, but I don&#39;t know the current date and location. I need to get the current date first, and then ask the user for their location.&quot; This step externalizes the AI&#39;s &quot;inner monologue,&quot; allowing us to track its logic and helping it clarify its own thought process.</p></li><li><p><strong>Action</strong></p><p>Based on the reasoning from the previous step, the AI decides to perform a specific action. Actions are typically executed by calling a <strong>tool</strong>.</p><p>For example:</p><ul><li>∙<code>Search[&quot;today&#39;s date&quot;]</code>(calling the search tool)</li><li>∙<code>Calculator[&quot;(25 * 4) / 2&quot;]</code>(calling the calculator tool)</li><li>∙<code>BrowseWebsite[&quot;a specific URL&quot;]</code>(calling the web browsing tool) It can also directly ask the user a question: <code>AskUser[&quot;Which city are you located in?&quot;]</code></li></ul></li><li><p><strong>Observation</strong></p><p>After the action is executed, the environment (or tool) returns a result. The AI receives and records this outcome.</p><p>For example, after searching for &quot;today&#39;s date,&quot; the observed result might be &quot;May 20, 2024.&quot; This observation becomes new information for solving the problem.</p></li></ol><p>The cycle then continues: the AI engages in <strong>a new round of reasoning</strong> based on all available information (the original question + newly observed results), decides on the next action, and repeats this process until it determines there is sufficient information to provide a final answer.</p><h3 id="max-iteration" tabindex="-1">Max Iteration <a class="header-anchor" href="#max-iteration" aria-label="Permalink to &quot;Max Iteration&quot;">​</a></h3><p>Set the maximum number of cycles for the Agent based on the ReAct framework, i.e., limit the number of <code>Thought → Action → Observation</code>loops to prevent the Agent from falling into an endless loop.</p><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote><h3 id="system-message" tabindex="-1">System Message <a class="header-anchor" href="#system-message" aria-label="Permalink to &quot;System Message&quot;">​</a></h3><p>Define the AI Agent&#39;s &quot;persona,&quot; role, behavioral guidelines, and conversational boundaries.</p><h3 id="user-message" tabindex="-1">User Message <a class="header-anchor" href="#user-message" aria-label="Permalink to &quot;User Message&quot;">​</a></h3><p>Assign a specific task instruction to the Agent.</p><h3 id="output-format" tabindex="-1">Output Format <a class="header-anchor" href="#output-format" aria-label="Permalink to &quot;Output Format&quot;">​</a></h3><p>Set the string output format for the Agent.</p><ul><li><strong>Raw (XML)</strong>: This is the Agent&#39;s native output format. The string may contain XML elements that document the Agent&#39;s thought process and tool invocations.</li><li><strong>Markdown</strong>: Converts the aforementioned XML markup into Markdown format.</li></ul><h3 id="enable-per-round-output" tabindex="-1">Enable per-round output <a class="header-anchor" href="#enable-per-round-output" aria-label="Permalink to &quot;Enable per-round output&quot;">​</a></h3><p>Once enabled, the Agent&#39;s thought process will be output in each ReAct iteration. If it&#39;s a Telegram trigger, a Telegram message will be sent.</p><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote><h3 id="mcp-tools" tabindex="-1">MCP Tools <a class="header-anchor" href="#mcp-tools" aria-label="Permalink to &quot;MCP Tools&quot;">​</a></h3><p>Here, you can select the MCP Server tools created by the <a href="https://doc.iolinker.com/mcp.html" target="_blank" rel="noreferrer">MCP trigger</a> from the workflow list. Once checked, the Agent will analyze the task and choose the corresponding tools to invoke accordingly.</p><h3 id="built-in-tools" tabindex="-1">Built-in Tools <a class="header-anchor" href="#built-in-tools" aria-label="Permalink to &quot;Built-in Tools&quot;">​</a></h3><p>Here are the built-in tools provided by the system. Users can select them as needed based on actual requirements.</p><ul><li><p>End Session。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>This function is used to end the current session or initiate a new one. When a user gives the Agent a clear termination intent, such as &quot;end&quot; or &quot;restart conversation,&quot; the Agent will interpret it as a request to end the current session or start a new one.</span></span></code></pre></div><p>Note: A single session may involve multiple dialogue records and potentially multiple workflow executions.</p></li><li><p>Ask Followup Question</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>The Agent asks the user questions to gather additional information needed to complete the task. This tool is used when the Agent encounters ambiguity, requires clarification, or needs more details to proceed effectively. It enables direct communication with the user, facilitating interactive problem-solving.</span></span></code></pre></div></li><li><p>Attempt Completion</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>After each tool usage by the Agent, the user will provide feedback on the tool&#39;s execution result—indicating success or failure, along with the reason for any failure. Upon receiving the tool execution result and confirming task completion, the Agent will use this tool to present the work outcome to the user.</span></span></code></pre></div></li><li><p>Use MCP Tool</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>The Agent will request to use tools provided by the connected MCP server based on the actual situation. Each MCP server can offer multiple tools with different functions.</span></span></code></pre></div></li><li><p>Web Fetch</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>When the Agent determines that it needs to retrieve and analyze web content, it will use this tool.</span></span></code></pre></div></li><li><p>Execute Command</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>When the Agent determines that system operations or specific commands need to be executed to complete any step of the user&#39;s task, it will use this function to run CLI commands on the system.</span></span></code></pre></div></li><li><p>Read File</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>When the Agent determines that it needs to inspect an existing file with unknown content—such as analyzing code, viewing a text file, or extracting information from a configuration file—it will use this function to request reading the content of the file at the specified path.</span></span></code></pre></div></li><li><p>Write To File</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Request to write content to a file at the specified path. If the file already exists, it will be overwritten with the provided content. If the file does not exist, it will be created. This tool automatically creates any directories required for writing the file.</span></span></code></pre></div></li><li><p>Search Files</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Request to perform a regular expression search on files in the specified directory and provide results with contextual information.</span></span></code></pre></div></li></ul><blockquote><p>Historical interface images are withheld pending review and recapture. Check operations against the current interface.</p></blockquote><h3 id="conversation-history" tabindex="-1">Conversation History <a class="header-anchor" href="#conversation-history" aria-label="Permalink to &quot;Conversation History&quot;">​</a></h3><ul><li>When the historical conversation feature is enabled, the Agent can achieve memory functionality, enabling coherent dialogues. <ul><li><strong>Conversation Rounds</strong>: Loads the most recent n turns of historical conversation records, with a maximum of 1000 turns loadable.</li><li><strong>Conversation Time(Minute)</strong>: Loads historical conversation records from the most recent n minutes, with records from up to 10 days ago being loadable.</li></ul></li></ul><h2 id="output" tabindex="-1">Output <a class="header-anchor" href="#output" aria-label="Permalink to &quot;Output&quot;">​</a></h2><ul><li><strong>content</strong>: The result returned by the Agent</li><li><strong>isSessionFinish</strong>: Indicates whether the current session has ended. If the historical conversation feature is not enabled, this value is always <code>true</code>, meaning the conversation is one-off. If the historical conversation feature is enabled, since the session involves multiple turns, intermediate execution results will set this value to <code>false</code>. Only when the Agent detects an explicit intent to end the session (e.g., by invoking the <code>End Session</code>tool), this value will be set to <code>true</code>.</li><li><strong>sessionId</strong>: The session ID. If historical conversation is enabled, the same <code>sessionId</code>will be used for intermediate interactions, indicating they belong to the same session.</li><li><strong>userId</strong>: The user associated with the session.</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;content&quot;: &quot;....&quot;,</span></span>
<span class="line"><span>        &quot;isSessionFinish&quot;: true,</span></span>
<span class="line"><span>        &quot;runId&quot;: &quot;379709981500375040&quot;,</span></span>
<span class="line"><span>        &quot;sessionId&quot;: &quot;e4da7671-aa01-41f3-9b51-826ea0955f6c&quot;,</span></span>
<span class="line"><span>        &quot;token&quot;: 0,</span></span>
<span class="line"><span>        &quot;userId&quot;: &quot;iolinker&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>]</span></span></code></pre></div>`,60)])])}const g=t(i,[["render",s]]);export{d as __pageData,g as default};
